    const a1 = getCodexDefaultProviders();
    const a2 = getCodexDefaultProviders();
    expect(a2).toBe(a1);
    expect((a1.gradingProvider as OpenAICodexSDKProvider).apiKey).toBe('key-a');
    expect((a1.gradingProvider as OpenAICodexSDKProvider).getApiKey()).toBe('key-a');

