    const o1 = getCodexDefaultProviders();
    mockProcessEnv({ CODEX_API_KEY: 'codex-y' });
    const o2 = getCodexDefaultProviders();
    expect(o2).toBe(o1);
    expect((o1.gradingProvider as OpenAICodexSDKProvider).apiKey).toBe('openai-1');

    // Rotating OPENAI -> new bundle
    mockProcessEnv({ OPENAI_API_KEY: 'openai-2' });
    const o3 = getCodexDefaultProviders();
